/**
 * Worker entry: the OpenNext-generated handler plus a cron trigger.
 * The hourly cron keeps an R2 snapshot of the GitHub project list so the
 * site still has data when GitHub is rate-limiting or down.
 */
import { PROJECTS_SNAPSHOT_KEY } from "./src/app/lib/github-snapshot";

// Generated by `opennextjs-cloudflare build`; absent until then.
// @ts-ignore
import openNext from "./.open-next/worker.js";

async function snapshotGithubProjects(env: CloudflareEnv): Promise<void> {
  // Goes through the app (service binding) so it shares the route's logic.
  if (!env.WORKER_SELF_REFERENCE) {
    throw new Error("WORKER_SELF_REFERENCE service binding is not configured");
  }
  const response = await env.WORKER_SELF_REFERENCE.fetch(
    "https://witl.xyz/api/github/projects?limit=20"
  );
  if (!response.ok) {
    throw new Error(`projects snapshot: upstream returned ${response.status}`);
  }

  const body = await response.text();
  const projects: unknown = JSON.parse(body);
  // Never replace a good snapshot with an empty (failed-upstream) result.
  if (!Array.isArray(projects) || projects.length === 0) return;

  await env.MEDIA.put(PROJECTS_SNAPSHOT_KEY, body, {
    httpMetadata: { contentType: "application/json" },
  });
}

export default {
  fetch: openNext.fetch,

  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(snapshotGithubProjects(env));
  },
} satisfies ExportedHandler<CloudflareEnv>;
